assignments.value:
={{ (() => {
  if ($('Search Case Form').isExecuted) return 'view_case';
  if ($('Select Client Action Form').isExecuted) {
    const act = (($('Select Client Action Form').first().json['Select Action'] || $('Select Client Action Form').first().json['Action'] || '')).toString().toLowerCase().trim();
    return act.includes('download') ? 'download' : 'view_invoice';
  }
  if ($('Invoice Event').first().json['User Type'] === 'Client') {
    return 'view_invoice';
  }
  if ($('Select Action').isExecuted) {
    const act = ($('Select Action').first().json.Action || '').toString().toLowerCase().trim();
    if (act === 'download') return 'download';
    if (act === 'update') return 'update';
    return 'view_invoice';
  }
  return 'view_invoice';
})() }}

