      '<tr><td bgcolor="#f8fafc" style="padding: 16px;">' +
        '<div style="font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; color: #475569; margin-bottom: 10px;"><b>Jotter</b></div>' +
        '<table width="100%" cellpadding="12" cellspacing="0" border="0" bgcolor="#4f46e5" style="border-radius: 6px; background-color: #4f46e5; width: 100%;">' +
          '<tr><td align="center" bgcolor="#4f46e5" style="text-align: center; background-color: #4f46e5; border-radius: 6px; padding: 12px;">' +
            '<a href="' + jUrl + '" target="_blank" style="color: #ffffff; text-decoration: none; display: block; width: 100%; font-weight: 700; font-size: 14px; font-family: sans-serif;">' +
              '<font color="#ffffff" size="3"><b>View Jotter Note</b></font>' +
            '</a>' +
          '</td></tr>' +
        '</table>' +
      '</td></tr>' +
    '</table>';
  }

  const vaultBlock = '<table width="100%" cellpadding="16" cellspacing="0" border="1" style="border-collapse: collapse; border: 1.5px solid #e2e8f0; border-radius: 8px; background-color: #f8fafc; margin: 12px 0;">' +
    '<tr><td bgcolor="#f8fafc" style="padding: 16px;">' +
      '<div style="font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; color: #475569; margin-bottom: 4px;"><b>Digital Document Vault</b></div>' +
      '<div style="font-size: 15px; font-weight: 600; color: #0f172a; margin-bottom: 12px;"><b>' + docTitle + '</b></div>' +
      '<table width="100%" cellpadding="12" cellspacing="0" border="0" bgcolor="#2563eb" style="border-radius: 6px; background-color: #2563eb; width: 100%;">' +
        '<tr><td align="center" bgcolor="#2563eb" style="text-align: center; background-color: #2563eb; border-radius: 6px; padding: 12px;">' +
          '<a href="' + docUrl + '" target="_blank" style="color: #ffffff; text-decoration: none; display: block; width: 100%; font-weight: 700; font-size: 14px; font-family: sans-serif;">' +
            '<font color="#ffffff" size="3"><b>View Original Document</b></font>' +
          '</a>' +
        '</td></tr>' +
      '</table>' +
    '</td></tr>' +
  '</table>';

  return '<div style="margin: 16px 0;">' + vaultBlock + jotterBlock + '<br><br></div>';
})() }}

